    def get_vaild_account(self, count=1):
        count = 1
        current_time = datetime.datetime.now()
        create_date = hashlib.md5(str('PBOXQT1.0V%s' % current_time.strftime('%Y%m%d')).encode('utf-8')).hexdigest()
        ptrade_account = None
        while datetime.datetime.now() - current_time <= datetime.timedelta(minutes=LOGIN_TIMEOUT):
            ptrade_account = AccountFactory.create_account(self.account_type, self.op_station, self.trade_id, create_date=create_date)
            error_dict = ptrade_account.init_connection()
            if error_dict.get('error_no') != 0:
                strategy_log.error(_('【login】第%s次与后端服务服务器连接建立失败' % count))
                count += 1
                ptrade_account = None
                time.sleep(LOGIN_FREQUENCY)
            else:
                kwargs = {'password': self.password, 'account_content': self.account_content, 'operator_no': self.account_content}
                error_dict, response = ptrade_account.login_account(**(kwargs))
                if error_dict.get('error_no') != 0:
                    ptrade_account = None
                    if get_trade_status(self.trade_id) == TradeStatus.TRADE_STOP:
                        break
                    strategy_log.error(_(f"【login】第{count!s}次后端服务登录失败，错误信息为：{error_dict.get('error_info')!s}"))
                    count += 1
                    time.sleep(LOGIN_FREQUENCY)
                else:
                    break
            LOGIN_TIMEOUT
        if ptrade_account is None:
            error_info = _('【login】登录失败，交易即将关闭')
            strategy_log.error(error_info)
            set_trade_stop_status(self.trade_id)
            raise RuntimeError(error_info)
        return ptrade_account
    def create_portfolio(self):
        Portfolio = ('Portfolio',)
        accounts = {}
        error_dict, response = fund_list_query(self.trade_account)
        while error_dict.get('error_no') != 0:
            system_log.error(_('后端服务操作账户资金信息查询失败，错误信息为:%s，等待60秒重新获取' % error_dict.get('error_info')))
            time.sleep(60)
            if not reconnect(self.trade_account, self.trade_id):
                break
            error_dict = fund_list_query(self.trade_account, self.business_type)
        if len(response) > 0:
            total_asset = float(response[0].get('total_asset', 0))
            if total_asset == 0:
                total_asset = float(response[0].get('asset_balance', 0))
            fund_balance = float(response[0].get('fund_balance', 0))
            market_value = float(response[0].get('market_value', 0))
            if total_asset == 0 and market_value + fund_balance > 0:
                total_asset = market_value + fund_balance
            units = total_asset
        else:
            market_value = 0
            total_asset = 0
            units = 0
        error_dict, response = fund_list_query(self.trade_account, business_type='hks')
        while error_dict.get('error_no') != 0:
            strategy_log.error(_('后端服务操作港股通账户资金信息查询失败，错误信息为:%s，等待60秒重新获取' % error_dict.get('error_info')))
            time.sleep(60)
            if not reconnect(self.trade_account, self.trade_id):
                break
            error_dict = fund_list_query(self.trade_account, business_type='hks')
        if len(response) > 0:
            starting_cash = float(response[0].get('enable_balance', 0))
        else:
            starting_cash = 0
        market_value = 0
        if stop_trade_switch == '1' and units == 0:
            strategy_log.error(f'资金查询用户总资产异常，error_dict：{error_dict!s}，response：{response!s}')
            strategy_log.error(_('用户总资产为0，为保护账户安全，关闭交易'))
            set_trade_stop_status(self.trade_id)
            return None
        account_model = self.engine.get_account_model(self.inter_acc_type)
        position_model = self.engine.get_position_model(self.inter_acc_type)
        positions = Positions(position_model)
        account = account_model(starting_cash, positions)
        position_list = position_list_query(self.trade_account, business_type=self.business_type)
        self.position_list = position_list
        for position in position_list:
            if position.get('exchange_type') not in EXCHANGE_TYPE_ENUM.keys():
                continue
            stock_code = f"{position.get('stock_code')!s}.{EXCHANGE_TYPE_ENUM[position.get('exchange_type')]!s}"
            if self.engine.get_asset(stock_code) is not None:
                stock_position = account.positions.get_or_create(stock_code)
                stock_position._amount = float(position['current_amount'])
                if float(position['current_amount']) != 0:
                    stock_position._avg_price = round(float(position.get('cost_balance', 0)) / float(position['current_amount']), 3)
                else:
                    stock_position._avg_price = 0
                stock_position._frozen = float(position.get('frozen_amount', 0))
                if 'last_price' in position.keys():
                    stock_position._last_price = float(position['last_price'])
                else:
                    stock_position._last_price = self.engine.data_proxy.get_snapshot(stock_code)[stock_code].get('last_px', 0)
                stock_position._enable_amount = int(float(position.get('enable_amount', 0)))
        else:
            accounts[self.inter_acc_type] = account
            return Portfolio(self.engine.config.strategy.start_date, 1, units, accounts)
    def create_sys_account(self, orders=None, after_trading_orders=None):
        current_time = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        account = {'cash': 0, 'total_cash': 0, 'frozen_cash': 0, 'total_asset': 0, 'market_value': 0, 'transaction_cost': 0, 'positions': {}}
        error_dict, response = fund_list_query(self.trade_account)
